import sys


def main():
    flags = set()
    filepath = None
    args = sys.argv[1:]

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            for ch in arg[1:]:
                if ch == 'l':
                    flags.add('l')
                elif ch == 'w':
                    flags.add('w')
                elif ch == 'c':
                    flags.add('c')
                else:
                    print(f"Unknown option: -{ch}", file=sys.stderr)
                    sys.exit(1)
        else:
            filepath = arg
        i += 1

    if not flags:
        flags = {'l', 'w', 'c'}

    # Determine input source
    if filepath is None or filepath == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, 'rb') as f:
            data = f.read()

    lines = data.count(b'\n')
    # A final line without trailing newline still counts
    if data and not data.endswith(b'\n'):
        lines += 1

    words = len(data.split())

    chars = len(data)

    order = [('l', 'lines'), ('w', 'words'), ('c', 'chars')]
    results = []
    for flag_key, _ in order:
        if flag_key in flags:
            results.append(str({
                'l': lines,
                'w': words,
                'c': chars
            }[flag_key]))

    print(' '.join(results))


if __name__ == '__main__':
    main()
